const { chromium } = require('playwright');
const path = require('path');
const fs = require('fs');

(async () => {
  const htmlPath = path.join(__dirname, 'index.html');
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Load the HTML file
  const content = fs.readFileSync(htmlPath, 'utf-8');
  await page.setContent(content, { waitUntil: 'load' });

  // Try to submit without answering any questions to trigger validation
  await page.click('button[type="submit"]');
  await page.waitForTimeout(500);

  // Inject and run axe-core
  const axeCorePath = require.resolve('axe-core');
  await page.addScriptTag({ path: axeCorePath });
  const result = await page.evaluate(async () => await window.axe.run());

  await browser.close();

  // Separate violations by type
  const wcag = result.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = result.violations.filter(v => v.tags.includes('best-practice'));

  // Report results
  console.log(JSON.stringify({
    wcag: wcag.map(v => ({
      id: v.id,
      impact: v.impact,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    })),
    bp: bp.map(v => ({
      id: v.id,
      targets: v.nodes.map(n => n.target)
    }))
  }, null, 2));

  process.exit(wcag.length > 0 ? 1 : 0);
})();

