 :root {
   --bg-primary: #1a1a1a;
   --bg-secondary: #2d2d2d;
   --bg-tertiary: #3a3a3a;
   --text-primary: #e8e8e8;
   --text-secondary: #b0b0b0;
   --accent: #6366f1;
   --accent-hover: #4f46e5;
   --border: #404040;
   --error: #ef4444;
   --success: #10b981;
   --focus: #818cf8;
 }

 * {
   margin: 0;
   padding: 0;
   box-sizing: border-box;
 }

 body {
   background-color: var(--bg-primary);
   color: var(--text-primary);
   font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
   font-size: 16px;
   line-height: 1.6;
   min-height: 100vh;
   padding: 20px;
 }

 main {
   width: 100%;
 }

 .container {
   max-width: 700px;
   margin: 0 auto;
 }

 h1 {
   font-size: 2rem;
   margin-bottom: 12px;
   font-weight: 700;
 }

 .intro {
   color: var(--text-secondary);
   margin-bottom: 32px;
   font-size: 0.95rem;
 }

 .form-field {
   background-color: var(--bg-secondary);
   border: 1px solid var(--border);
   border-radius: 8px;
   padding: 24px;
   margin-bottom: 24px;
   font-size: 1rem;

   legend {
     font-weight: 600;
     font-size: 1.1rem;
     margin-bottom: 16px;
     display: block;
     color: var(--text-primary);

     span {
       color: var(--error);
     }
   }
 }

 .help-text {
   color: var(--text-secondary);
   font-size: 0.9rem;
   margin-bottom: 16px;
   margin-top: -8px;
 }

 .checkbox-option {
   display: flex;
   align-items: center;
   margin-bottom: 12px;
   gap: 12px;
 }

 input[type="checkbox"] {
   width: 18px;
   height: 18px;
   min-width: 18px;
   min-height: 18px;
   cursor: pointer;
   accent-color: var(--accent);
   border: 2px solid var(--border);
   border-radius: 4px;
   background-color: var(--bg-tertiary);
   transition: all 0.2s ease;

   &:hover:not(:disabled) {
     border-color: var(--accent);
     background-color: var(--bg-tertiary);
   }

   &:focus-visible {
     outline: 2px solid var(--focus);
     outline-offset: 2px;
   }

   &:checked {
     background-color: var(--accent);
     border-color: var(--accent);
   }

   &:disabled {
     opacity: 0.6;
     cursor: not-allowed;
   }
 }

 label {
   cursor: pointer;
   color: var(--text-primary);
   user-select: none;
   transition: color 0.2s ease;

   &:hover {
     color: var(--accent);
   }
 }

 .error-message {
   color: var(--error);
   font-size: 0.9rem;
   margin-top: 16px;
   display: none;

   &:not([hidden]) {
     display: block;
   }
 }

 .form-field[aria-invalid="true"] {
   border-color: var(--error);
   background-color: rgba(239, 68, 68, 0.05);
 }

 .form-actions {
   display: flex;
   gap: 12px;
   margin-top: 32px;
   margin-bottom: 24px;
 }

 .submit-btn {
   background-color: var(--accent);
   color: white;
   border: none;
   padding: 12px 32px;
   font-size: 1rem;
   font-weight: 600;
   border-radius: 6px;
   cursor: pointer;
   transition: all 0.2s ease;

   &:hover {
     background-color: var(--accent-hover);
     transform: translateY(-1px);
     box-shadow: 0 4px 12px rgba(99, 102, 241, 0.3);
   }

   &:focus-visible {
     outline: 2px solid var(--focus);
     outline-offset: 2px;
   }

   &:active {
     transform: translateY(0);
   }

   &:disabled {
     opacity: 0.6;
     cursor: not-allowed;
     transform: none;
   }
 }

 .form-error-summary {
   background-color: rgba(239, 68, 68, 0.1);
   border: 1px solid var(--error);
   border-radius: 6px;
   padding: 16px;
   color: #fca5a5;
   margin-top: 16px;

   p {
     margin: 0;
     font-weight: 500;
   }

   &:not([hidden]) {
     display: block;
   }
 }

 .form-success-summary {
   background-color: rgba(16, 185, 129, 0.1);
   border: 1px solid var(--success);
   border-radius: 6px;
   padding: 16px;
   color: #86efac;
   margin-top: 16px;

   p {
     margin: 0;
     font-weight: 500;
   }

   &:not([hidden]) {
     display: block;
   }
 }

 /* Responsive design */
 @media (max-width: 480px) {
   h1 {
     font-size: 1.5rem;
   }

   .form-field {
     padding: 16px;
   }

   .submit-btn {
     width: 100%;
   }
 }

 /* Forced Colors mode support */
 @media (prefers-contrast: more) {
   .form-field {
     border-width: 2px;
   }

   input[type="checkbox"] {
     border-width: 2px;
   }

   .submit-btn {
     border: 2px solid currentColor;
   }
 }

 /* Reduced motion support */
 @media (prefers-reduced-motion: reduce) {
   input[type="checkbox"],
   label,
   .submit-btn {
     transition: none;
   }
 }

