      <form id="quiz-form" novalidate>
        <fieldset class="form-field" aria-describedby="q1-help q1-error">
          <legend>Which of these are statically-typed languages? <span aria-hidden="true">*</span></legend>
          <p id="q1-help" class="help-text">Select all that apply. A statically-typed language checks types at compile time.</p>

          <div class="checkbox-option">
            <input id="q1-java" type="checkbox" name="q1" value="java">
            <label for="q1-java">Java</label>
          </div>

          <div class="checkbox-option">
            <input id="q1-python" type="checkbox" name="q1" value="python">
            <label for="q1-python">Python</label>
          </div>

          <div class="checkbox-option">
            <input id="q1-typescript" type="checkbox" name="q1" value="typescript">
            <label for="q1-typescript">TypeScript</label>
          </div>

          <div class="checkbox-option">
            <input id="q1-javascript" type="checkbox" name="q1" value="javascript">
            <label for="q1-javascript">JavaScript</label>
          </div>

          <p id="q1-error" class="error-message" hidden></p>
        </fieldset>

        <fieldset class="form-field" aria-describedby="q2-error">
          <legend>Which languages are compiled? <span aria-hidden="true">*</span></legend>

          <div class="checkbox-option">
            <input id="q2-c" type="checkbox" name="q2" value="c">
            <label for="q2-c">C</label>
          </div>

          <div class="checkbox-option">
            <input id="q2-go" type="checkbox" name="q2" value="go">
            <label for="q2-go">Go</label>
          </div>

          <div class="checkbox-option">
            <input id="q2-ruby" type="checkbox" name="q2" value="ruby">
            <label for="q2-ruby">Ruby</label>
          </div>

          <div class="checkbox-option">
            <input id="q2-rust" type="checkbox" name="q2" value="rust">
            <label for="q2-rust">Rust</label>
          </div>

          <p id="q2-error" class="error-message" hidden></p>
        </fieldset>

        <fieldset class="form-field" aria-describedby="q3-error">
          <legend>Which languages run on the JVM? <span aria-hidden="true">*</span></legend>

          <div class="checkbox-option">
            <input id="q3-java" type="checkbox" name="q3" value="java">
            <label for="q3-java">Java</label>
          </div>

          <div class="checkbox-option">
            <input id="q3-kotlin" type="checkbox" name="q3" value="kotlin">
            <label for="q3-kotlin">Kotlin</label>
          </div>

          <div class="checkbox-option">
            <input id="q3-scala" type="checkbox" name="q3" value="scala">
            <label for="q3-scala">Scala</label>
          </div>

          <div class="checkbox-option">
            <input id="q3-csharp" type="checkbox" name="q3" value="csharp">
            <label for="q3-csharp">C#</label>
          </div>

          <p id="q3-error" class="error-message" hidden></p>
        </fieldset>

        <div class="form-actions">
          <button type="submit" class="submit-btn">Submit Quiz</button>
        </div>

        <div id="form-error" class="form-error-summary" hidden role="alert">
          <p>Please answer all questions before submitting.</p>
        </div>

        <div id="form-success" class="form-success-summary" hidden role="status">
          <p>Quiz submitted successfully!</p>
        </div>
      </form>
    </div>
  </main>

  <script>
document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('quiz-form');
  const formErrorSummary = document.getElementById('form-error');
  const formSuccessSummary = document.getElementById('form-success');

  form.addEventListener('submit', (e) => {
    e.preventDefault();

    formErrorSummary.hidden = true;
    formSuccessSummary.hidden = true;

    const questions = ['q1', 'q2', 'q3'];
    let hasError = false;

    questions.forEach((questionId) => {
      const fieldset = form.querySelector(`fieldset[aria-describedby*="${questionId}"]`);
      const checkboxes = form.querySelectorAll(`input[name="${questionId}"]`);
      const errorElement = document.getElementById(`${questionId}-error`);

      const isChecked = Array.from(checkboxes).some(cb => cb.checked);

      if (!isChecked) {
        hasError = true;
        fieldset.setAttribute('aria-invalid', 'true');
        errorElement.hidden = false;
        errorElement.textContent = `Error: Please select at least one answer for this question.`;
        if (!fieldset.classList.contains('error-highlight')) {
          fieldset.classList.add('error-highlight');
        }
      } else {
        fieldset.removeAttribute('aria-invalid');
        errorElement.hidden = true;
        fieldset.classList.remove('error-highlight');
      }
    });

    if (hasError) {
      formErrorSummary.hidden = false;
      const firstError = form.querySelector('fieldset[aria-invalid="true"]');
      if (firstError) {
        firstError.scrollIntoView({ behavior: 'smooth', block: 'center' });
        firstError.focus();
      }
    } else {
      const answers = {};
      questions.forEach((questionId) => {
        const checkedBoxes = form.querySelectorAll(`input[name="${questionId}"]:checked`);
        answers[questionId] = Array.from(checkedBoxes).map(cb => cb.value);
      });

      formSuccessSummary.hidden = false;
      formSuccessSummary.scrollIntoView({ behavior: 'smooth', block: 'center' });

      console.log('Quiz answers:', answers);
    }
  });

  const allCheckboxes = form.querySelectorAll('input[type="checkbox"]');
  allCheckboxes.forEach((checkbox) => {
    checkbox.addEventListener('change', () => {
      const questionId = checkbox.name;
      const fieldset = form.querySelector(`fieldset[aria-describedby*="${questionId}"]`);
      const checkboxes = form.querySelectorAll(`input[name="${questionId}"]`);
      const isChecked = Array.from(checkboxes).some(cb => cb.checked);

      if (isChecked && fieldset.getAttribute('aria-invalid') === 'true') {
        fieldset.removeAttribute('aria-invalid');
        const errorElement = document.getElementById(`${questionId}-error`);
        errorElement.hidden = true;
        fieldset.classList.remove('error-highlight');
      }
    });
  });
});
  </script>
</body>
</html>
